@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard — @WarehouseState.CurrentWarehouseName</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentAlertCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted">
                    @if (_polling)
                    {
                        <span>🟢 Polling every 10 s</span>
                    }
                    else
                    {
                        <span>⏸ Polling stopped</span>
                    }
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private bool _polling;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await PollOnceAsync();
            StateHasChanged();
        });
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _polling = true;
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        // Initial poll immediately
        await PollOnceAsync();
        await InvokeAsync(StateHasChanged);

        while (await timer.WaitForNextTickAsync(ct))
        {
            await PollOnceAsync();
            // No need to call StateHasChanged here — UpdateAlertCount fires
            // OnAlertCountChanged, which triggers StateHasChanged in all subscribers
        }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        AlertService.UpdateAlertCount(count);
    }

    public void Dispose()
    {
        _polling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}
